// Compiles San Francisco's surveyed elevated highway bridges, viaducts, ramps, and untagged overpasses
// (`sf/bridges-survey.json.br`, generated by `bay/bridges_survey.py`) into compact binary bytes (`bay/bridges.bin`)
// loaded once on the page and shared with every core before it makes sectors (#228).
//
//   node sf/bridges.mjs [survey.json.br] [out.bin]
//
// Binary format (little-endian):
//   Header (5 int32 words = 20 bytes):
//     [0] magic   = 'BRDG' (0x47445242)
//     [1] version = 1
//     [2] nSpans  = number of bridge spans
//     [3] nVerts  = total vertices across all spans
//     [4] nPiers  = number of concrete viaduct piers
//   Then `nSpans` span records, each:
//     uint16  flags    (0:motorway, 1:barL, 2:barR, 3:piers, 4:capS, 5:capE, 6..8:lanes, 9..11:layer+2, 12:twoWay)
//     uint8   thick    (structural box-girder slab thickness in 10 cm cells)
//     uint8   reserved (0)
//     uint16  m        (vertex count >= 2)
//     uint16  pad      (0)
//     Vertex 0 (16 bytes): int32 x0, int32 z0, int32 y4_0, uint8 hl0, uint8 hr0, uint8 vflags0, uint8 pad
//     Vertices 1..m-1 (10 bytes each): int16 dx, int16 dz, int16 dy4, uint8 hl, uint8 hr, uint8 vflags, uint8 pad
//   Then `nPiers` pier records (20 bytes each):
//     int32 x, int32 z, int16 y_top, int16 y_bot, uint8 rad, int8 nx, int8 nz, uint8 pad, uint8 cap_l, uint8 cap_r, uint16 pad2
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { brotliDecompressSync } from 'node:zlib'

const HERE = dirname(fileURLToPath(import.meta.url))
export const DEFAULT_SURVEY = join(HERE, 'bridges-survey.json.br')
export const MAGIC = 0x47445242 // 'BRDG'
const VERSION = 1
const MAX_DELTA = 30000

/** Read a `.json.br` (or plain `.json`) bridges survey from disk. */
export function bridgesSurvey(path = DEFAULT_SURVEY) {
  if (!path || !existsSync(path)) return { version: 1, frame: '10n4250', spans: [], piers: [] }
  const raw = readFileSync(path)
  const text = path.endsWith('.br') ? brotliDecompressSync(raw).toString('utf8') : raw.toString('utf8')
  return JSON.parse(text)
}

/** Subdivide any span segment whose delta exceeds int16 range. */
function normalizeVerts(verts) {
  if (!Array.isArray(verts) || verts.length < 2) return []
  const out = [verts[0]]
  for (let i = 1; i < verts.length; i++) {
    const a = out[out.length - 1], b = verts[i]
    const dx = b[0] - a[0], dz = b[1] - a[1], dy = b[2] - a[2]
    if (dx === 0 && dz === 0) continue
    const steps = Math.max(1, Math.ceil(Math.max(Math.abs(dx), Math.abs(dz), Math.abs(dy)) / MAX_DELTA))
    for (let s = 1; s <= steps; s++) {
      const u = s / steps
      out.push([
        Math.round(a[0] + dx * u),
        Math.round(a[1] + dz * u),
        Math.round(a[2] + dy * u),
        Math.round(a[3] + (b[3] - a[3]) * u),
        Math.round(a[4] + (b[4] - a[4]) * u),
        s === steps ? b[5] : a[5],
      ])
    }
  }
  return out.length >= 2 ? out : []
}

/** Pack a parsed bridges survey object into compact `bay/bridges.bin` bytes for `bay.rs`. */
export function bridgesBytes(survey) {
  const spans = []
  let nVerts = 0
  let spanBytes = 0
  for (const s of survey?.spans ?? []) {
    const v = normalizeVerts(s.v)
    if (v.length < 2 || v.length > 4096) continue
    spans.push({
      flags: (s.flags ?? 0) & 0xffff,
      thick: Math.max(4, Math.min(40, s.thick ?? 12)),
      v,
    })
    nVerts += v.length
    spanBytes += 8 + 16 + (v.length - 1) * 10
  }
  const piers = (survey?.piers ?? []).filter((p) => Array.isArray(p) && p.length >= 9)
  const totalBytes = 20 + spanBytes + piers.length * 20
  const buf = Buffer.alloc(totalBytes)
  buf.writeInt32LE(MAGIC, 0)
  buf.writeInt32LE(VERSION, 4)
  buf.writeInt32LE(spans.length, 8)
  buf.writeInt32LE(nVerts, 12)
  buf.writeInt32LE(piers.length, 16)
  let off = 20
  for (const s of spans) {
    const m = s.v.length
    buf.writeUInt16LE(s.flags, off)
    buf.writeUInt8(s.thick, off + 2)
    buf.writeUInt8(0, off + 3)
    buf.writeUInt16LE(m, off + 4)
    buf.writeUInt16LE(0, off + 6)
    off += 8
    const v0 = s.v[0]
    buf.writeInt32LE(v0[0], off)
    buf.writeInt32LE(v0[1], off + 4)
    buf.writeInt32LE(v0[2], off + 8)
    buf.writeUInt8(Math.max(10, Math.min(255, v0[3])), off + 12)
    buf.writeUInt8(Math.max(10, Math.min(255, v0[4])), off + 13)
    buf.writeUInt8(v0[5] & 0xff, off + 14)
    buf.writeUInt8(0, off + 15)
    off += 16
    for (let i = 1; i < m; i++) {
      const prev = s.v[i - 1], cur = s.v[i]
      buf.writeInt16LE(cur[0] - prev[0], off)
      buf.writeInt16LE(cur[1] - prev[1], off + 2)
      buf.writeInt16LE(cur[2] - prev[2], off + 4)
      buf.writeUInt8(Math.max(10, Math.min(255, cur[3])), off + 6)
      buf.writeUInt8(Math.max(10, Math.min(255, cur[4])), off + 7)
      buf.writeUInt8(cur[5] & 0xff, off + 8)
      buf.writeUInt8(0, off + 9)
      off += 10
    }
  }
  for (const p of piers) {
    buf.writeInt32LE(p[0], off)
    buf.writeInt32LE(p[1], off + 4)
    buf.writeInt16LE(Math.max(-32767, Math.min(32767, p[2])), off + 8)
    buf.writeInt16LE(Math.max(-32767, Math.min(32767, p[3])), off + 10)
    buf.writeUInt8(Math.max(4, Math.min(30, p[4])), off + 12)
    buf.writeInt8(Math.max(-127, Math.min(127, p[5])), off + 13)
    buf.writeInt8(Math.max(-127, Math.min(127, p[6])), off + 14)
    buf.writeUInt8(0, off + 15)
    buf.writeUInt8(Math.max(0, Math.min(255, p[7])), off + 16)
    buf.writeUInt8(Math.max(0, Math.min(255, p[8])), off + 17)
    buf.writeUInt16LE(0, off + 18)
    off += 20
  }
  return buf
}

/** Load the committed bridges survey and compile it to `bay/bridges.bin` bytes. */
export function bridgesBin(path = DEFAULT_SURVEY) {
  return bridgesBytes(bridgesSurvey(path))
}

/** Short human summary of a bridges.bin buffer. */
export function said(bytes) {
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  return `${dv.getInt32(8, true)} spans, ${dv.getInt32(12, true)} vertices, ${dv.getInt32(16, true)} piers, ${bytes.length} bytes`
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop())) {
  const surveyPath = process.argv[2] || DEFAULT_SURVEY
  const outPath = process.argv[3]
  const bytes = bridgesBin(surveyPath)
  if (outPath) writeFileSync(outPath, bytes)
  console.log(`  elevated bridges: ${said(bytes)}`)
}
